body.query:
query {
  r0: repository(owner:"VHP4Safety", name:"virtual-human-platform") { ...repoBits }
  r1: repository(owner:"VHP4Safety", name:"cloud") { ...repoBits }
  r2: repository(owner:"VHP4Safety", name:"ui-casestudy-config") { ...repoBits }
  r3: repository(owner:"VHP4Safety", name:"glossary") { ...repoBits }
  r4: repository(owner:"marvinm2", name:"AOPWikiRDF") { ...repoBits }
  r5: repository(owner:"marvinm2", name:"AOP-Wiki-Snorql-UI") { ...repoBits }
  r6: repository(owner:"marvinm2", name:"AOP-Wiki-RDF-dashboard") { ...repoBits }
  r7: repository(owner:"marvinm2", name:"molAOP-builder") { ...repoBits }
  r8: repository(owner:"marvinm2", name:"molAOP-analyser") { ...repoBits }
  r9: repository(owner:"johannehouweling", name:"ToxTempAssistant") { ...repoBits }
}

fragment repoBits on Repository {
  nameWithOwner pushedAt isArchived stargazerCount
  primaryLanguage { name }
  licenseInfo { spdxId }
  releases(first:100, orderBy:{field:CREATED_AT, direction:DESC}) {
    nodes { tagName publishedAt isDraft }
  }
  refs(refPrefix:"refs/tags/", first:100,
       orderBy:{field:TAG_COMMIT_DATE, direction:DESC}) {
    nodes { name target { ... on Commit { committedDate }
                          ... on Tag { target { ... on Commit { committedDate } } } } }
  }
}
